import { BackgroundOrchestrator } from "./BackgroundOrchestrator";
import { RTLCanvas } from "./RTLCanvas";
import { SlideSurface } from "./SlideSurface";
import { buildSlides } from "./utils/buildSlides";
import { pairSplitGreetings } from "./utils/pairSpreads";
import type { AlbumConfig, AlbumSlide } from "./types";

/** A single printed sheet: the opening cover alone, then open spreads. */
export interface PrintSheet {
  key: string;
  leaves: AlbumSlide[];
}

/**
 * Lays an album out as printed sheets, exactly as the flip book lays it out on
 * screen: the front cover opens alone and everything after it reads as a
 * spread, so a reader who knows the digital album recognises the paper one.
 *
 * The pairing is the book's own, spacers and all — a greeting split into words
 * and photo is never dealt across two sheets.
 */
export function paginate(
  album: AlbumConfig,
  showBackCover = true,
): PrintSheet[] {
  const leaves = pairSplitGreetings(buildSlides(album, { showBackCover }));
  const [cover, ...rest] = leaves;
  const sheets: PrintSheet[] = [{ key: cover.key, leaves: [cover] }];

  for (let i = 0; i < rest.length; i += 2) {
    const pair = rest.slice(i, i + 2);
    sheets.push({ key: pair[0].key, leaves: pair });
  }
  return sheets;
}

export interface PrintBookProps {
  album: AlbumConfig;
  /** Append the closing cover, as the book does. Defaults to true. */
  showBackCover?: boolean;
  /** Number the leaves along the foot of each page. Defaults to true. */
  pageNumbers?: boolean;
  className?: string;
}

/**
 * Print-ready rendering of an album.
 *
 * The interactive book sizes itself to the window, which a browser cannot
 * paginate. This lays the same leaves onto fixed sheets instead and leaves the
 * export to the browser's own print-to-PDF. Geometry lives in `print.css`,
 * which is a separate entry point because it carries an `@page` rule that must
 * only reach documents that are actually printing an album.
 */
export function PrintBook({
  album,
  showBackCover = true,
  pageNumbers = true,
  className,
}: PrintBookProps) {
  const sheets = paginate(album, showBackCover);

  // Numbering counts content leaves only, so a spacer does not consume one.
  let counter = 0;
  const numbers = new Map<string, number>();
  for (const sheet of sheets) {
    for (const leaf of sheet.leaves) {
      if (leaf.kind === "page") numbers.set(leaf.key, ++counter);
    }
  }

  return (
    <RTLCanvas
      themeColor={album.themeColor}
      className={["ae-print", className].filter(Boolean).join(" ")}
    >
      {sheets.map((sheet) => (
        <BackgroundOrchestrator
          key={sheet.key}
          global={album.globalBackground}
          className="ae-print__sheet"
        >
          <div
            className={`ae-print__book ae-print__book--${
              sheet.leaves.length > 1 ? "spread" : "single"
            }`}
          >
            {sheet.leaves.map((leaf) => (
              <div key={leaf.key} className="ae-print__leaf">
                {renderLeaf(album, leaf)}
                {pageNumbers && numbers.has(leaf.key) ? (
                  <span className="ae-print__number" aria-hidden="true">
                    {numbers.get(leaf.key)} / {counter}
                  </span>
                ) : null}
              </div>
            ))}
          </div>
        </BackgroundOrchestrator>
      ))}
    </RTLCanvas>
  );
}

/** Shared with the flip book's leaf rendering, so paper matches screen. */
function renderLeaf(album: AlbumConfig, slide: AlbumSlide) {
  return <SlideSurface album={album} slide={slide} />;
}
